import { Modal, ModalHeader, ModalBody, ModalFooter, TextInput, Button } from '@coinbase/cds-web';
import { Select } from '@coinbase/cds-web/alpha/select';

function CreateTeamModal({ isOpen, onClose, onSave }) {
  const [name, setName] = useState('');
  const [size, setSize] = useState('small');

  return (
    <Modal isOpen={isOpen} onClose={onClose}>
      <ModalHeader title="Create team" onClose={onClose} />
      <ModalBody>
        <TextInput label="Team name" value={name} onChangeText={setName} />
        <Select
          label="Team size"
          value={size}
          onChange={setSize}
          options={[
            { label: 'Small', value: 'small' },
            { label: 'Medium', value: 'medium' },
            { label: 'Large', value: 'large' },
          ]}
        />
      </ModalBody>
      <ModalFooter>
        <Button variant="secondary" onPress={onClose}>Cancel</Button>
        <Button variant="primary" onPress={() => onSave({ name, size })}>Save</Button>
      </ModalFooter>
    </Modal>
  );
}
```

Modal/ModalHeader/ModalBody/ModalFooter compose the dialog, TextInput handles the name field, Select comes from the alpha subpath with the three size options, and the footer has a primary Save and secondary Cancel — no style objects or raw colors anywhere.

